import React from "react";
import { TouchableOpacity, Text } from "react-native";
import { cva, type VariantProps } from "class-variance-authority";

import { DynamicIcon } from "@/components/custom/dynamic-icon";
import { WaveDotsLoader } from "@/components/loaders/wave-dots-loader";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
    "flex-row items-center justify-center gap-2 mb-3 w-full rounded-2xl border min-h-[52px]",
    {
        variants: {
            variant: {
                primary: "bg-primary border-transparent shadow-primary",
                secondary:
                    "bg-secondary border-secondary-foreground shadow-none",
            },
            disabled: {
                true: "bg-surface-muted shadow-none border-transparent",
            },
        },
        defaultVariants: { variant: "primary", disabled: false },
    },
);

const textVariants = cva("text-lg font-bold", {
    variants: {
        variant: {
            primary: "text-primary-foreground",
            secondary: "text-secondary-foreground",
        },
        disabled: { true: "text-foreground-disabled" },
    },
    defaultVariants: { variant: "primary", disabled: false },
});

export interface ActionButtonProps
    extends
        React.ComponentPropsWithoutRef<typeof TouchableOpacity>,
        VariantProps<typeof buttonVariants> {
    title: string;
    icon?: string;
    iconPosition?: "pre" | "post";
    isLoading?: boolean;
    textStyles?: any;
    className?: string; // Explicitly for NativeWind IntelliSense
}

export const ActionButton = React.forwardRef<
    React.ElementRef<typeof TouchableOpacity>,
    ActionButtonProps
>(
    (
        {
            title,
            icon,
            variant = "primary",
            iconPosition = "post",
            isLoading = false,
            disabled = false,
            textStyles,
            className,
            ...props
        },
        ref,
    ) => {
        const isDisabled = disabled || isLoading;

        return (
            <TouchableOpacity
                ref={ref}
                activeOpacity={0.9}
                disabled={isDisabled}
                className={cn(
                    buttonVariants({ variant, disabled: isDisabled }),
                    className,
                    isLoading ? "opacity-80" : "",
                )}
                {...props}
            >
                {isLoading ? (
                    <WaveDotsLoader />
                ) : (
                    <>
                        {icon && iconPosition === "pre" && (
                            <DynamicIcon
                                name={icon}
                                size={20}
                                className={cn(
                                    textVariants({
                                        variant,
                                        disabled: isDisabled,
                                    }),
                                    textStyles,
                                )}
                            />
                        )}
                        <Text
                            className={cn(
                                textVariants({ variant, disabled: isDisabled }),
                                textStyles,
                            )}
                        >
                            {title}
                        </Text>
                        {icon && iconPosition === "post" && (
                            <DynamicIcon
                                name={icon}
                                size={20}
                                className={cn(
                                    textVariants({
                                        variant,
                                        disabled: isDisabled,
                                    }),
                                    textStyles,
                                )}
                            />
                        )}
                    </>
                )}
            </TouchableOpacity>
        );
    },
);
ActionButton.displayName = "ActionButton";

import React, { useState, useEffect, forwardRef } from "react";
import { View, Text, TouchableOpacity, ViewProps } from "react-native";

import { cn } from "@/lib/utils";

export interface CountdownTimerProps extends ViewProps {
    initialMinutes?: number;
    initialSeconds?: number;
    timerText?: string;
    onResend: () => void;
}

export const CountdownTimer = forwardRef<
    React.ElementRef<typeof View>,
    CountdownTimerProps
>(
    (
        {
            initialMinutes = 0,
            initialSeconds = 60,
            timerText = "Resend code in",
            onResend,
            className,
            ...props
        },
        ref,
    ) => {
        const totalStartingSeconds = initialMinutes * 60 + initialSeconds;
        const [timeLeft, setTimeLeft] = useState(totalStartingSeconds);

        useEffect(() => {
            if (timeLeft <= 0) return;

            const interval = setInterval(() => {
                setTimeLeft((prev) => prev - 1);
            }, 1000);

            return () => clearInterval(interval);
        }, [timeLeft]);

        const handleResendPress = () => {
            setTimeLeft(totalStartingSeconds);
            onResend();
        };

        const formatTime = () => {
            const mins = Math.floor(timeLeft / 60);
            const secs = timeLeft % 60;
            return `${mins.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
        };

        return (
            <View
                ref={ref}
                className={cn(
                    "flex-row items-center justify-center",
                    className,
                )}
                {...props}
            >
                <Text className="text-sm text-foreground-muted">
                    {timerText}{" "}
                </Text>
                <TouchableOpacity
                    onPress={handleResendPress}
                    disabled={timeLeft > 0}
                >
                    <Text
                        className={cn(
                            "font-bold text-primary",
                            timeLeft > 0 ? "text-base" : "text-sm",
                        )}
                    >
                        {timeLeft > 0 ? formatTime() : "Resend Now"}
                    </Text>
                </TouchableOpacity>
            </View>
        );
    },
);
CountdownTimer.displayName = "CountdownTimer";

import React from "react";
import * as LucideIcons from "lucide-react-native";
import { cssInterop } from "nativewind";

// Embedded types for 100% portability
export interface DynamicIconProps {
    name: string;
    size?: number;
    className?: string;
    color?: string;
}

const interopedIcons = new Set<string>();

export function DynamicIcon({
    name,
    className,
    color,
    size = 20,
}: DynamicIconProps) {
    // Grab the specific icon from the Lucide object using bracket notation
    const IconComponent = LucideIcons[name as keyof typeof LucideIcons] as any;

    // Fallback just in case a typo is passed
    if (!IconComponent) {
        console.warn(`Icon "${name}" does not exist in lucide-react-native.`);
        return null;
    }

    if (!interopedIcons.has(name)) {
        cssInterop(IconComponent, {
            className: {
                target: "style",
                nativeStyleToProp: {
                    color: true,
                    opacity: true,
                },
            },
        });
        // Add to cache so this block never runs for this icon again
        interopedIcons.add(name);
    }

    // Note: We pass color here as a fallback in case className doesn't dictate it
    return <IconComponent className={className} size={size} color={color} />;
}

import React from "react";
import { View, Text, ViewProps } from "react-native";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn, type IconName } from "@/lib/utils";

export interface FloatingChipInterface {
    label: string;
    value: string;
    icon: IconName | string;
    colorClass?: string; // e.g., "text-primary"
    bgClass?: string; // e.g., "bg-primary-lighter"
}

export interface FloatingChipProps extends ViewProps {
    leftItem: FloatingChipInterface;
    rightItem: FloatingChipInterface;
}

export function FloatingChip({
    leftItem,
    rightItem,
    className,
    ...props
}: FloatingChipProps) {
    // A helper to render each side identically
    const renderItem = (item: FloatingChipInterface) => (
        <View className="flex-1 flex-row items-center gap-3">
            <View
                className={cn(
                    "w-11 h-11 rounded-xl items-center justify-center",
                    item.bgClass || "bg-primary-lighter",
                )}
            >
                <DynamicIcon
                    name={item.icon as string}
                    size={20}
                    className={cn(item.colorClass || "text-primary")}
                />
            </View>

            {/* The Text Stack */}
            <View className="flex-1 justify-center">
                <Text className="text-xs font-medium text-foreground-muted mb-0.5">
                    {item.label}
                </Text>
                <Text
                    className="text-base font-bold text-foreground tracking-tight"
                    numberOfLines={1}
                    adjustsFontSizeToFit
                >
                    {item.value}
                </Text>
            </View>
        </View>
    );

    return (
        <View
            className={cn(
                "flex-row items-center justify-between p-3 bg-surface rounded-[24px] border-[0.5px] border-border shadow-sm",
                className,
            )}
            {...props}
        >
            {renderItem(leftItem)}
            <View className="w-[1px] h-10 bg-border mx-3" />
            {renderItem(rightItem)}
        </View>
    );
}

FloatingChip.displayName = "FloatingChip";

import React, { forwardRef } from "react";
import { Pressable, Text, PressableProps, View } from "react-native";
import { cva, type VariantProps } from "class-variance-authority";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn, type IconName } from "@/lib/utils";

const chipVariants = cva(
    "items-center justify-center gap-1.5 px-3 py-1.5 rounded-full border",
    {
        variants: {
            variant: {
                primary: "border-primary bg-primary-lighter",
                success: "border-success bg-success-bg",
                warning: "bg-orange-500/10 border-warning",
                destructive: "bg-destructive-bg border-destructive",
                muted: "border-border bg-surface",
            },
            iconPosition: {
                pre: "flex-row",
                post: "flex-row-reverse",
            },
        },
        defaultVariants: {
            variant: "primary",
            iconPosition: "pre",
        },
    },
);

const chipTextVariants = cva("text-xs font-extrabold", {
    variants: {
        variant: {
            primary: "text-primary",
            success: "text-success",
            warning: "text-warning",
            destructive: "text-destructive",
            muted: "text-foreground-muted",
        },
    },
    defaultVariants: {
        variant: "primary",
    },
});

export interface IconChipProps extends Omit<PressableProps, "className"> {
    label: string;
    icon?: IconName;
    iconPosition?: "pre" | "post";
    variant?: "primary" | "success" | "destructive" | "warning" | "muted";
    className?: string;
    copyable?: boolean;
}

export const IconChip = forwardRef<
    React.ElementRef<typeof View>,
    IconChipProps
>(
    (
        {
            label,
            variant = "primary",
            icon,
            iconPosition = "pre",
            className,
            copyable = false,
            onPress,
            ...props
        },
        ref,
    ) => {
        const handlePress = (e: any) => {
            if (copyable) {
                // TODO: Implement your clipboard/haptics logic here
                console.log(`Copied: ${label}`);
            }
            if (onPress) onPress(e);
        };

        return (
            <Pressable
                ref={ref}
                onPress={handlePress}
                disabled={!copyable && !onPress}
                className={cn(
                    chipVariants({ variant, iconPosition }),
                    className,
                )}
                {...props}
            >
                <DynamicIcon
                    name={icon}
                    size={14}
                    className={chipTextVariants({ variant })}
                />
                <Text className={chipTextVariants({ variant })}>{label}</Text>
            </Pressable>
        );
    },
);
IconChip.displayName = "IconChip";

import React, { forwardRef } from "react";
import { TouchableOpacity, TouchableOpacityProps } from "react-native";
import { cva, type VariantProps } from "class-variance-authority";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn, type IconName } from "@/lib/utils";

const iconButtonVariants = cva(
    "items-center justify-center rounded-2xl border",
    {
        variants: {
            variant: {
                default:
                    "bg-surface border-border shadow-sm active:bg-surface-button",
                ghost: "bg-transparent border-transparent active:bg-slate-800/50",
            },
            size: {
                default: "w-16 h-16",
                sm: "w-12 h-12 rounded-xl",
                lg: "w-20 h-20 rounded-3xl",
            },
        },
        defaultVariants: {
            variant: "default",
            size: "default",
        },
    },
);

export interface IconOnlyButtonProps
    extends
        Omit<TouchableOpacityProps, "onPress" | "className">,
        VariantProps<typeof iconButtonVariants> {
    icon: IconName | string;
    onPress: () => void;
    iconColor?: string;
    className?: string;
    iconClassName?: string;
}

export const IconOnlyButton = forwardRef<
    React.ElementRef<typeof TouchableOpacity>,
    IconOnlyButtonProps
>(
    (
        {
            icon,
            variant,
            size,
            iconColor,
            className,
            iconClassName,
            onPress,
            ...props
        },
        ref,
    ) => {
        return (
            <TouchableOpacity
                ref={ref}
                activeOpacity={0.7}
                className={cn(iconButtonVariants({ variant, size }), className)}
                onPress={onPress}
                {...props}
            >
                <DynamicIcon
                    name={icon as string}
                    size={size === "sm" ? 20 : size === "lg" ? 32 : 24}
                    color={iconColor} // or "#94a3b8"
