                />
            </TouchableOpacity>
        );
    },
);
IconOnlyButton.displayName = "IconOnlyButton";

import { useState, forwardRef } from "react";
import { Text, TextInput, View, TextInputProps } from "react-native";
import { Controller, FieldValues, Control, Path } from "react-hook-form";
import { cva, type VariantProps } from "class-variance-authority";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn } from "@/lib/utils";

const inputWrapperVariants = cva(
    "flex-row items-center rounded-xl border bg-slate-900 overflow-hidden",
    {
        variants: {
            variant: {
                default: "border-slate-800",
                error: "border-destructive",
            },
            disabled: {
                true: "opacity-50 bg-slate-800/50",
            },
        },
        defaultVariants: {
            variant: "default",
            disabled: false,
        },
    },
);

export interface InputProps
    extends
        Omit<TextInputProps, "onChangeText">,
        VariantProps<typeof inputWrapperVariants> {
    label: string;
    value: string;
    onChangeText: (text: string) => void;
    error?: string;
    type?: "mobile" | "email" | "password" | "number" | "text";
    prefix?: string;
    className?: string; // Standardize user overrides
}

export interface ControlledInputProps<T extends FieldValues> extends Omit<
    InputProps,
    "value" | "onChangeText"
> {
    control: Control<T>;
    name: Path<T>;
}

export const Input = forwardRef<TextInput, InputProps>(
    (
        {
            label,
            value,
            type = "text",
            placeholder,
            maxLength,
            onChangeText,
            error,
            disabled,
            autoFocus = false,
            prefix = "+91",
            className,
            ...rest
        },
        ref,
    ) => {
        const [showSecureText, setShowSecureText] = useState(true);
        const hasError = !!error;

        return (
            <View className="mb-5">
                <Text className="text-xs font-medium text-slate-400 mb-2">
                    {label}
                </Text>

                <View
                    className={cn(
                        inputWrapperVariants({
                            variant: hasError ? "error" : "default",
                            disabled,
                        }),
                        className,
                    )}
                >
                    {type === "mobile" && (
                        <View className="justify-center px-4 border-r border-slate-800">
                            <Text className="text-base font-medium text-white">
                                {prefix}
                            </Text>
                        </View>
                    )}

                    <TextInput
                        ref={ref}
                        className="flex-1 px-4 py-4 text-base font-medium text-white"
                        placeholder={placeholder}
                        maxLength={maxLength}
                        placeholderTextColor="#64748b"
                        secureTextEntry={type === "password" && showSecureText}
                        keyboardType={
                            type === "mobile" || type === "number"
                                ? "number-pad"
                                : type === "email"
                                  ? "email-address"
                                  : "default"
                        }
                        autoCapitalize={
                            type === "email" || type === "password"
                                ? "none"
                                : "sentences"
                        }
                        value={value}
                        onChangeText={onChangeText}
                        autoFocus={autoFocus}
                        editable={!disabled}
                        {...rest}
                    />

                    {type === "password" && value?.length ? (
                        <DynamicIcon
                            name={showSecureText ? "EyeClosed" : "Eye"}
                            size={20}
                            color="#94a3b8"
                            style={{ paddingHorizontal: 16 }}
                            onPress={() => setShowSecureText((prev) => !prev)}
                        />
                    ) : null}
                </View>

                {hasError ? (
                    <Text className="text-xs mt-1.5 font-medium text-destructive">
                        {error}
                    </Text>
                ) : null}
            </View>
        );
    },
);
Input.displayName = "Input";

export function ControlledInput<T extends FieldValues>({
    control,
    name,
    ...rest
}: ControlledInputProps<T>) {
    return (
        <Controller
            control={control}
            name={name}
            render={({
                field: { onChange, value },
                fieldState: { fieldError },
            }) => (
                <Input
                    value={value as string}
                    onChangeText={onChange}
                    error={fieldError?.message}
                    {...rest}
                />
            )}
        />
    );
}
ControlledInput.displayName = "ControlledInput";

import React, { useRef, forwardRef, useImperativeHandle } from "react";
import { View, Text, TextInput, Pressable, ViewProps } from "react-native";

import { cn } from "@/lib/utils";

export interface OTPInputBoxProps extends ViewProps {
    code: string;
    setCode: (code: string) => void;
    length?: number;
}

export interface OTPInputRef {
    focus: () => void;
    blur: () => void;
    clear: () => void;
}

export const OTPInputBox = forwardRef<OTPInputRef, OTPInputBoxProps>(
    ({ code, setCode, length = 6, className, ...props }, ref) => {
        const inputRef = useRef<TextInput>(null);

        useImperativeHandle(ref, () => ({
            focus: () => inputRef.current?.focus(),
            blur: () => inputRef.current?.blur(),
            clear: () => setCode(""),
        }));

        const handlePress = () => {
            if (inputRef.current?.isFocused()) {
                inputRef.current.blur();
                setTimeout(() => {
                    inputRef.current?.focus();
                }, 50);
            } else {
                inputRef.current?.focus();
            }
        };

        return (
            <View className={cn("w-full items-center", className)} {...props}>
                <Pressable
                    className="w-full flex-row justify-between"
                    onPress={handlePress}
                >
                    {Array(length)
                        .fill(0)
                        .map((_, index) => {
                            const digit = code[index] || "";
                            const isCurrentDigit = index === code.length;
                            const isLastDigit = index === length - 1;
                            const isCodeComplete = code.length === length;
                            const isFocused =
                                isCurrentDigit ||
                                (isCodeComplete && isLastDigit);

                            return (
                                <View
                                    key={index}
                                    className={cn(
                                        "h-16 w-14 items-center justify-center rounded-xl border-2",
                                        isFocused
                                            ? "border-primary bg-primary-lighter"
                                            : "bg-surface border-transparent",
                                    )}
                                >
                                    <Text
                                        className={cn(
                                            "text-2xl font-medium",
                                            isFocused
                                                ? "text-primary"
                                                : "text-foreground",
                                        )}
                                    >
                                        {digit}
                                    </Text>
                                </View>
                            );
                        })}
                </Pressable>

                <TextInput
                    ref={inputRef}
                    value={code}
                    onChangeText={(text) => {
                        const numericValue = text.replace(/[^0-9]/g, "");
                        if (numericValue.length <= length)
                            setCode(numericValue);
                    }}
                    keyboardType="number-pad"
                    autoFocus
                    textContentType="oneTimeCode"
                    className="absolute h-0 w-0 opacity-0"
                />
            </View>
        );
    },
);
OTPInputBox.displayName = "OTPInputBox";

import React, { useState, forwardRef } from "react";
import {
    View,
    Text,
    Modal,
    FlatList,
    Pressable,
    TextInput,
    TouchableOpacity,
    ViewProps,
} from "react-native";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn } from "@/lib/utils";

import { COUNTRIES, type CountryProps } from "@/constants/data/countries";

export interface PhoneInputProps extends ViewProps {
    value: string;
    onChangeText: (text: string) => void;
    selectedCountry: CountryProps;
    onCountryChange: (country: CountryProps) => void;
    countries?: CountryProps[];
}

export const PhoneInput = forwardRef<
    React.ElementRef<typeof View>,
    PhoneInputProps
>(
    (
        {
            value,
            onChangeText,
            selectedCountry,
            onCountryChange,
            countries = COUNTRIES, // Defaults to the imported list if not provided
            className,
            ...props
        },
        ref,
    ) => {
        const [isFocused, setIsFocused] = useState(false);
        const [isPickerVisible, setPickerVisible] = useState(false);

        const handleTextChange = (text: string) => {
            const numericValue = text.replace(/[^0-9]/g, "");
            if (numericValue.length <= selectedCountry.maxLength) {
                onChangeText(numericValue);
            }
        };

        return (
            <View ref={ref} className={cn("mb-6", className)} {...props}>
                <Text className="text-sm font-medium text-foreground-muted mb-2 ml-1">
                    Enter your phone number
                </Text>

                <View
                    className={cn(
                        "flex-row items-center bg-surface rounded-2xl border-[1.5px] h-16",
                        isFocused ? "border-primary" : "border-transparent",
                    )}
                >
                    <TouchableOpacity
                        activeOpacity={0.7}
                        onPress={() => setPickerVisible(true)}
                        className="flex-row items-center h-full pl-4 rounded-l-2xl"
                    >
                        <Text className="text-2xl mr-2">
                            {selectedCountry.flag}
                        </Text>
                        <Text className="text-foreground text-lg font-semibold mr-1">
                            {selectedCountry.dialCode}
                        </Text>
                        <DynamicIcon
                            name="ChevronDown"
                            size={18}
                            className="text-foreground-muted"
                        />
                    </TouchableOpacity>

                    <View className="w-[1px] h-8 bg-border mx-2" />

                    <TextInput
                        value={value}
                        onChangeText={handleTextChange}
                        onFocus={() => setIsFocused(true)}
                        onBlur={() => setIsFocused(false)}
                        keyboardType="number-pad"
                        placeholder="000 000 0000"
                        placeholderTextColor="#9ca3af" // Tailwind gray-400
                        className="flex-1 h-full text-foreground text-lg font-semibold px-2"
                        maxLength={selectedCountry.maxLength}
                    />
                </View>

                <Modal
                    visible={isPickerVisible}
                    transparent
                    animationType="slide"
                >
                    <Pressable
                        className="flex-1 bg-black/50 justify-end"
                        onPress={() => setPickerVisible(false)}
                    >
                        <View className="bg-background rounded-t-[32px] max-h-[70%] overflow-hidden">
                            <View className="w-full items-center pt-4 pb-2">
                                <View className="w-12 h-1.5 bg-surface-muted rounded-full" />
                            </View>

                            <Text className="text-xl font-bold text-foreground px-6 py-4">
                                Select Country
                            </Text>

                            <FlatList
                                data={countries}
                                keyExtractor={(item) => item.id}
                                className="px-4 pb-8"
                                renderItem={({ item }) => (
                                    <TouchableOpacity
                                        activeOpacity={0.7}
                                        onPress={() => {
                                            onCountryChange(item);
                                            setPickerVisible(false);
                                        }}
                                        className={cn(
                                            "flex-row items-center justify-between p-4 rounded-2xl mb-2",
                                            selectedCountry.id === item.id
                                                ? "bg-surface-muted"
                                                : "bg-transparent",
                                        )}
                                    >
                                        <View className="flex-row items-center">
                                            <Text className="text-3xl mr-4">
                                                {item.flag}
                                            </Text>
                                            <Text className="text-foreground font-semibold text-lg">
                                                {item.name}
                                            </Text>
                                        </View>
                                        <Text className="text-foreground-muted font-medium">
                                            {item.dialCode}
                                        </Text>
                                    </TouchableOpacity>
                                )}
                            />
                        </View>
                    </Pressable>
                </Modal>
            </View>
        );
    },
);
PhoneInput.displayName = "PhoneInput";

export interface CountryProps {
    id: string;
    name: string;
    dialCode: string;
    flag: string;
    maxLength: number;
}
export const COUNTRIES: CountryProps[] = [
    { id: "IN", name: "India", dialCode: "+91", flag: "🇮🇳", maxLength: 10 },
    {
        id: "US",
        name: "United States",
        dialCode: "+1",
        flag: "🇺🇸",
        maxLength: 10,
    },
    {
        id: "UK",
